#!/usr/bin/env node
// Copies compiled ABIs from ../contracts/out and deployment addresses from ../deployments
// into src/generated/ as typed TS modules (`as const` so viem infers argument/return types).
// If the sources are missing (fresh clone without `forge build`), the existing generated files are kept.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const web = join(here, '..');
const outDir = join(web, '..', 'contracts', 'out');
const depDir = join(web, '..', 'deployments');
const genDir = join(web, 'src', 'generated');

const CONTRACTS = {
  FishingGame: 'fishingGameAbi',
  FishNFT: 'fishNftAbi',
  GameLens: 'gameLensAbi',
  PearlToken: 'pearlTokenAbi',
  Marketplace: 'marketplaceAbi',
  PearlExchange: 'pearlExchangeAbi',
  Tournaments: 'tournamentsAbi',
  BottlePool: 'bottlePoolAbi',
  DailyRewards: 'dailyRewardsAbi',
  SeasonHunt: 'seasonHuntAbi',
  ReelJudge: 'reelJudgeAbi',
};

mkdirSync(genDir, { recursive: true });
const header = '// AUTO-GENERATED by scripts/sync-abi.mjs — do not edit by hand. Run `pnpm sync`.\n';

let wroteAbi = 0;
for (const [name, exportName] of Object.entries(CONTRACTS)) {
  const src = join(outDir, `${name}.sol`, `${name}.json`);
  const dst = join(genDir, `${name}.ts`);
  if (!existsSync(src)) {
    if (existsSync(dst)) {
      console.warn(`[sync] ${src} not found, keeping existing ${name}.ts`);
      continue;
    }
    console.error(`[sync] ${src} not found. Run \`forge build\` in contracts/ first.`);
    process.exit(1);
  }
  const { abi } = JSON.parse(readFileSync(src, 'utf8'));
  writeFileSync(dst, `${header}export const ${exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`);
  wroteAbi++;
}

const depDst = join(genDir, 'deployments.ts');
const deployments = {};
if (existsSync(depDir)) {
  for (const f of readdirSync(depDir)) {
    if (!/^\d+\.json$/.test(f)) continue;
    const d = JSON.parse(readFileSync(join(depDir, f), 'utf8'));
    deployments[String(d.chainId ?? f.replace('.json', ''))] = {
      chainId: Number(d.chainId),
      startBlock: Number(d.startBlock ?? 0),
      game: d.game,
      fish: d.fish,
      lens: d.lens,
      pearl: d.pearl,
      market: d.market,
      ...(d.blend && d.exchange ? { blend: d.blend, exchange: d.exchange } : {}),
      ...(d.tournaments ? { tournaments: d.tournaments } : {}),
      ...(d.bottles ? { bottles: d.bottles } : {}),
      ...(d.dailyRewards ? { dailyRewards: d.dailyRewards } : {}),
      ...(d.seasonHunt ? { seasonHunt: d.seasonHunt } : {}),
    };
  }
}
if (!existsSync(depDir) && existsSync(depDst)) {
  console.warn('[sync] ../deployments not found, keeping existing deployments.ts');
} else {
  const type =
    'export interface Deployment {\n  chainId: number;\n  startBlock: number;\n  game: `0x${string}`;\n  fish: `0x${string}`;\n  lens: `0x${string}`;\n  pearl: `0x${string}`;\n  market: `0x${string}`;\n  /** Set once the BLEND → PEARL exchange is deployed. */\n  blend?: `0x${string}`;\n  exchange?: `0x${string}`;\n  /** Set once the tournaments are deployed. */\n  tournaments?: `0x${string}`;\n  /** The BLEND bottle pool, once the game pays bottles out of it. */\n  bottles?: `0x${string}`;\n  /** The reward for a full day of daily challenges, once it is deployed. Without it the client offers no claim. */\n  dailyRewards?: `0x${string}`;\n  /** The season hunt, once it is deployed. Without it the Season Hunt page says so. */\n  seasonHunt?: `0x${string}`;\n}\n';
  writeFileSync(
    depDst,
    `${header}${type}\nexport const deployments: Record<string, Deployment> = ${JSON.stringify(deployments, null, 2)};\n`,
  );
}

// Weekly seasons: three hunts of the season hunt shown as one event (src/game/week.ts). The week file says what the
// week is called and how it was planned; the record, written by the script that created the hunts, says which
// on-chain seasons they are. A record made for another hunt contract than the deployed one is left out.
const weekDir = join(web, '..', 'contracts', 'script', 'seasons', 'weeks');
const recordDir = join(depDir, 'weeks');
const weeks = {};
let weekCount = 0;
if (existsSync(recordDir)) {
  for (const chain of readdirSync(recordDir)) {
    if (!/^\d+$/.test(chain) || !deployments[chain]?.seasonHunt) continue;
    for (const f of readdirSync(join(recordDir, chain)).sort()) {
      if (!f.endsWith('.json')) continue;
      const rec = JSON.parse(readFileSync(join(recordDir, chain, f), 'utf8'));
      const src = join(weekDir, `${rec.id}.json`);
      if (rec.version !== 1 || !Array.isArray(rec.huntIds) || rec.huntIds.length !== 3 || !existsSync(src)) {
        console.warn(`[sync] week record ${chain}/${f} is not a week of this repository, skipped`);
        continue;
      }
      if (String(rec.seasonHunt).toLowerCase() !== deployments[chain].seasonHunt.toLowerCase()) {
        console.warn(`[sync] week record ${chain}/${f} is for another hunt contract, skipped`);
        continue;
      }
      const file = JSON.parse(readFileSync(src, 'utf8'));
      const start = Date.parse(file.start) / 1000;
      (weeks[chain] ??= []).push({
        id: file.id,
        title: file.title,
        description: file.description,
        ...(file.theme ? { theme: file.theme } : {}),
        start,
        end: start + file.days * 86400,
        hunts: rec.huntIds.map((seasonId, i) => ({ seasonId: Number(seasonId), difficulty: file.hunts[i].difficulty })),
      });
      weekCount++;
    }
  }
}
writeFileSync(
  join(genDir, 'weeks.ts'),
  `${header}import type { WeekEntry } from '../game/week';\n\n/** Weekly seasons by chain id: which on-chain seasons are the three hunts of each. */\nexport const weeks: Record<string, WeekEntry[]> = ${JSON.stringify(weeks, null, 2)};\n`,
);

console.log(`[sync] ABIs: ${wroteAbi} written, deployments: ${Object.keys(deployments).join(', ') || 'none'}, weekly seasons: ${weekCount}`);
